import {db} from './api.js';
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let month=new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'}).slice(0,7);
export async function mountCalendar(root,user,defaults){
 if(!root)return;
 root.innerHTML=`<div class="page-heading events-heading"><h1>${user.is_admin?'Events':'Events calendar'}</h1><div class="actions events-controls"><label>Month <input class="input" type="month" id="calendar-month" value="${month}"></label>${user.is_admin?'<button class="btn primary" id="add-event" aria-label="Add event">+ Add event</button>':''}</div></div><p id="calendar-feedback" role="status">Loading events…</p><div class="month-grid"></div><div class="month-agenda"></div>`;
 root.querySelector('#calendar-month').onchange=e=>{if(e.target.value){month=e.target.value;mountCalendar(root,user,defaults);}};
 root.querySelector('#add-event')?.addEventListener('click',()=>{
 const dialog=document.createElement('dialog');dialog.className='event-editor';dialog.innerHTML=`<h2>Add event</h2><form><label class="field">Event name<input class="input" name="title" required maxlength="160"></label><label class="field">Date<input class="input" name="date" type="date" value="${month}-01" required></label><p role="status"></p><div class="actions"><button class="btn primary">Save event</button><button class="btn" type="button" data-cancel>Cancel</button></div></form>`;document.body.append(dialog);dialog.showModal();dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();dialog.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target),button=e.target.querySelector('button');button.disabled=true;const title=String(form.get('title')).trim();if(!title){button.disabled=false;return;}const {error}=await db.from('calendar_events').insert({title,event_date:form.get('date'),created_by:user.id});if(error){dialog.querySelector('[role="status"]').textContent='Unable to save event. Please try again.';button.disabled=false;return;}month=String(form.get('date')).slice(0,7);dialog.close();mountCalendar(root,user,defaults);};
 });
 const [year,m]=month.split('-').map(Number),days=new Date(year,m,0).getDate(),start=new Date(year,m-1,1).getDay(),end=`${month}-${String(days).padStart(2,'0')}`;
 const {data,error}=await db.from('calendar_events').select('event_date,title').gte('event_date',month+'-01').lte('event_date',end).order('event_date');if(!root.isConnected)return;
 const feedback=root.querySelector('#calendar-feedback');feedback.textContent=error?'Saved events could not be loaded. Please reopen the calendar.':'';
 const byDate={};Object.entries(defaults).filter(([date])=>date.startsWith(month)).forEach(([date,title])=>byDate[date]=[title]);(data||[]).forEach(e=>(byDate[e.event_date]??=[]).push(e.title));
 const entries=[];for(let day=1;day<=days;day++){const date=`${month}-${String(day).padStart(2,'0')}`,sunday=new Date(year,m-1,day).getDay()===0;const events=[...(byDate[date]||[])];entries.push({day,date,events});}
 root.querySelector('.month-grid').innerHTML=['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(d=>`<strong>${d}</strong>`).join('')+'<div></div>'.repeat(start)+entries.map(e=>`<button class="calendar-day ${e.events.length?'has-events':''}" data-day="${e.date}" aria-label="${e.date}, ${e.events.length} events"><strong>${e.day}</strong>${e.events.length?'<span>•</span>':''}</button>`).join('');
 root.querySelector('.month-agenda').innerHTML=entries.filter(e=>e.events.length).map(e=>`<section class="calendar-event-row" id="event-${e.date}"><time datetime="${e.date}"><strong>${e.day}</strong><span>${escape(new Date(e.date+'T12:00:00').toLocaleDateString('en',{month:'short'}))}</span></time><div>${e.events.map(t=>`<p>${escape(t)}</p>`).join('')}</div><svg class="icon event-bell" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4"/></svg></section>`).join('')||'<p class="calendar-empty">No events this month.</p>';
 root.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>root.querySelector('#event-'+b.dataset.day)?.scrollIntoView({behavior:'smooth',block:'center'}));
}
